const GOALTOPIC={"Data, analytics or IT role":["Technology / information systems"],"Sales or business development role":["Sales / business development"],"Hospitality or events role":["Hospitality / tourism / events"],"Finance or real estate role":["Finance / banking / insurance / real estate"],"Retail or consumer goods role":["Retail / consumer goods"],"Media or entertainment business role":["Entertainment / sports / media"],"Startup or small business role":["Entrepreneurship / startups"],"Start my own business":["Entrepreneurship / startups"],"Accounting or audit role (CPA path)":["Accounting / professional services"],"Government or nonprofit role":["Government / nonprofit / public policy"],"Supply chain or operations role":["Supply chain / logistics / operation"],"Healthcare administration role":["Healthcare administration"],"Marketing or brand role":["Marketing / advertising / public relations"],"Exploring consulting or data roles":["Consulting","Technology / information systems"]};
