const short = t => t.split(" / ")[0];
const DEFAULT_WEIGHTS = Object.freeze({ major: 3, interest: 3, goal: 2, past: 2 });
const TARGET = Object.freeze({ Freshman: 20, Sophomore: 40, Junior: 60, Senior: 85 });
const GRACE_ID = "P046";

/* Fresh, mutable student objects (source line 225). Call once per page load; "Start over" calls it again. */
function makeStudents() {
  return RAW.map(r => ({ id: r[0], name: r[1], major: r[2], year: r[3], events: r[4] ? r[4].split(";") : [], interests: r[5] ? r[5].split(";") : [], goal: r[6] || "", tb: r[7], viaAI: false }));
}

/* Source lines 233-252. w is required here (her default was the live slider state S.w). */
function score(st, ev, w) {
  w = w || DEFAULT_WEIGHTS;
  const fMajor = ev.major === st.major ? 1 : 0;
  const hit = st.interests.filter(t => ev.topics.includes(t));
  const fInt = hit.length ? 1 : 0;
  const gt = GOALTOPIC[st.goal] || [];
  const fGoal = gt.some(t => ev.topics.includes(t)) ? 1 : 0;
  const related = st.events.filter(e => PAST[e] && PAST[e][2].some(t => ev.topics.includes(t)));
  const fPast = related.length >= 2 ? 1 : related.length === 1 ? .5 : 0;
  const total = w.major * fMajor + w.interest * fInt + w.goal * fGoal + w.past * fPast;
  const r = [];
  if (fInt) r.push(`said they're interested in ${short(hit[0]).toLowerCase()}`);
  if (fGoal) r.push(`career goal fits`);
  if (fPast) r.push(`went to ${related.length} similar event${related.length > 1 ? "s" : ""}`);
  if (fMajor) r.push(`same major`);
  const info = st.interests.length || st.goal ? "Profile card" : st.events.length ? "Major + events" : "Major only";
  let reason = r.join("; ");
  if (!r.length) reason = "No match on file";
  else if (info === "Major only") reason += "; nothing else on file";
  return { total, reason, info, fInt, fGoal, fPast, fMajor, hit, related };
}

const infoRank = i => i === "Profile card" ? 2 : i === "Major + events" ? 1 : 0;
const yr = y => ({ Freshman: 1, Sophomore: 2, Junior: 3, Senior: 4 })[y] || 0;

/* Career Hub ranking (source line 546): drop total 0, sort, keep top 30. The table shows the first 15. */
function rankStudents(students, ev, w) {
  return students.map(s => ({ s, ...score(s, ev, w) })).filter(r => r.total > 0)
    .sort((a, b) => b.total - a.total || infoRank(b.info) - infoRank(a.info) || yr(b.s.year) - yr(a.s.year) || a.s.tb - b.s.tb)
    .slice(0, 30);
}

/* Student "Events for me" (source line 356): always the default weights, stable sort by total, top 3. */
function rankEvents(student) {
  return UPCOMING.map(e => ({ ...e, ...score(student, e, DEFAULT_WEIGHTS) })).sort((a, b) => b.total - a.total).slice(0, 3);
}

/* "Why you" wording for the student view (source line 362). */
function whyYou(r) {
  return r.total ? r.reason.replace("said they're", "you said you're").replace("career goal fits", "fits your next step").replace("same major", "popular with your major") : "open to all students";
}

/* Illustrative readiness for the 300 (source lines 468-473). Returns [year, average %, % on track, count]. */
function hubReadiness(students) {
  const by = { Freshman: [], Sophomore: [], Junior: [], Senior: [] };
  students.forEach(s => { const base = { Freshman: 8, Sophomore: 18, Junior: 28, Senior: 38 }[s.year] || 10; const v = Math.min(100, base + s.events.length * 7 + ((s.interests.length || s.goal) ? 8 : 0) + (s.tb % 17)); (by[s.year] || []).push(v); });
  return Object.entries(by).filter(([, a]) => a.length).map(([y, a]) => { const avg = Math.round(a.reduce((x, z) => x + z, 0) / a.length); const on = Math.round(a.filter(v => v >= TARGET[y]).length / a.length * 100); return [y, avg, on, a.length]; });
}

const MAJOR_SHORT = { "International Business & Marketing": "IB & Marketing", "Management & Human Resources": "Management & HR", "Finance, Real Estate & Law": "Finance, RE & Law", "Computer Information Systems": "CIS", "Technology & Operations Management": "Tech & Ops Mgmt" };

/* Term overview numbers (source lines 502-507). */
function overviewStats(students) {
  const n = students.length, att = students.filter(s => s.events.length).length, cards = students.filter(s => s.interests.length || s.goal).length;
  const byMajor = {}; students.forEach(s => s.events.forEach(() => byMajor[s.major] = (byMajor[s.major] || 0) + 1));
  const first = {}; students.forEach(s => { if (s.events[0]) first[s.events[0]] = (first[s.events[0]] || 0) + 1; });
  const tot = {}; students.forEach(s => s.events.forEach(e => tot[e] = (tot[e] || 0) + 1));
  const firstTimers = Object.keys(tot).map(e => [PAST[e][0], Math.round((first[e] || 0) / tot[e] * 100)]).sort((a, b) => b[1] - a[1]).slice(0, 6);
  const attendanceByMajor = Object.entries(byMajor).sort((a, b) => b[1] - a[1]).map(([k, v]) => [MAJOR_SHORT[k] || k, v]);
  return { n, attended: att, cards, neverReached: n - att, attendanceByMajor, firstTimers };
}

/* Sample check-in pattern (source lines 372-378). 29x29 grid; returns the dark 1x1 cells plus the three finder origins. Not a scannable code. */
function qrCells(id) {
  let seed = [...id].reduce((a, c) => a * 31 + c.charCodeAt(0), 7); const rnd = () => (seed = (seed * 9301 + 49297) % 233280) / 233280;
  const cells = [];
  for (let y = 1; y < 28; y++) for (let x = 1; x < 28; x++) { const inF = (x < 9 && y < 9) || (x > 19 && y < 9) || (x < 9 && y > 19); if (!inF && rnd() > .55) cells.push([x, y]); }
  return { size: 29, cells, finders: [[1, 1], [21, 1], [1, 21]] };
}

/* Puts Grace in the state the guided demo path leaves her in (DESIGN.md section 2.4). Used by the iv=done deep link and by selfTest. */
function applyGuidedInterview(grace) {
  grace.interests = ["Technology / information systems", "Entertainment / sports / media"];
  grace.goal = "Exploring consulting or data roles";
  grace.viaAI = true;
  return grace;
}

/* Test vectors from DESIGN.md section 3.5. Run SMC.selfTest() in the console: every row must have pass === true. */
function selfTest() {
  const out = []; const ok = (name, got, want) => out.push({ name, got: JSON.stringify(got), want: JSON.stringify(want), pass: JSON.stringify(got) === JSON.stringify(want) });
  let st = makeStudents(); let g = st.find(s => s.id === GRACE_ID); const ev = id => UPCOMING.find(e => e.id === id);
  ok("TV0 counts", [st.length, UPCOMING.length, TOPICS.length, Object.keys(PAST).length, Object.keys(GOALTOPIC).length], [300,5,13,10,14]);
  ok("TV1 Grace before interview, events for me", rankEvents(g).map(e => [e.id, e.total]), [["U3",3],["U1",1],["U2",1]]);
  ok("TV2 Grace before interview, E11 rank", rankStudents(st, ev("E11"), DEFAULT_WEIGHTS).findIndex(r => r.s.id === GRACE_ID), -1);
  applyGuidedInterview(g);
  ok("TV3 Grace after interview, events for me", rankEvents(g).map(e => [e.id, e.total]), [["E11",6],["U2",4],["U1",3]]);
  ok("TV4 E11 default weights, top 8", rankStudents(st, ev("E11"), DEFAULT_WEIGHTS).slice(0, 8).map(r => [r.s.id, r.total]), [["P108",8],["P224",8],["P028",6],["P046",6],["P286",6],["P004",5],["P178",5],["P131",5]]);
  ok("TV5 E11 same major = 10, top 8", rankStudents(st, ev("E11"), { major: 10, interest: 3, goal: 2, past: 2 }).slice(0, 8).map(r => [r.s.id, r.total]), [["P108",15],["P224",15],["P028",13],["P286",13],["P220",11],["P124",11],["P168",10],["P208",10]]);
  ok("TV6 U3 default weights, top 5", rankStudents(st, ev("U3"), DEFAULT_WEIGHTS).slice(0, 5).map(r => [r.s.id, r.total]), [["P049",9],["P192",7],["P225",7],["P276",6],["P072",6]]);
  ok("TV7 overview", (o => [o.n, o.attended, o.cards, o.neverReached])(overviewStats(makeStudents())), [300,100,70,200]);
  ok("TV8 hub readiness", hubReadiness(makeStudents()), [["Freshman",22,56,34],["Sophomore",33,20,35],["Junior",42,7,103],["Senior",51,0,128]]);
  return out;
}

